// SIEGEBREAK entry program for make.fun best-game-01 (Node 22, standard library only).
// SIEGEBREAK is a physics siege game where the last engineer of a fallen kingdom defends honor
// against ten formidable castles using a trebuchet.
//
// Deliverable Layout:
// - game/: plain static files (index.html, ES modules under src/) loaded offline by desktop browsers with no network requests.
// - screenshots/: 3 to 4 PNG/JPEG renders documenting the game, with the first acting as the cover.
// - dossier.json: canonical summary generated by buildDossier from ./vendor/makefun-game.ts.
//
// Determinism Contract:
// The entry program runs twice and both runs must write identical bytes. It copies files directly
// and never writes timestamps or random data, ensuring byte-for-byte reproducibility.
//
// Gate Caps Enforced through buildDossier:
// - text_max_bytes: 163840 bytes
// - screenshots: max 4 files, max 262144 bytes each
// - game_max_files: 993 files
// - game_max_bytes: 50331648 bytes
// - game_path_max_bytes: 1000 bytes
//
// Serve locally with node serve.ts, then open http://localhost:8080.
// Outside container: MAKEFUN_OUTPUT_DIR=out node main.ts

import { cpSync, existsSync, mkdirSync, readdirSync, writeFileSync } from 'node:fs';
import { join } from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildDossier } from './vendor/makefun-game.ts';

const here = fileURLToPath(new URL('.', import.meta.url));
const out = process.env.MAKEFUN_OUTPUT_DIR ?? '/output';

/**
 * Verify that game/index.html exists and that screenshots directory holds between 3 and 4 files.
 */
function verifyInputs(baseDir: string): void {
  const indexPath = join(baseDir, 'game', 'index.html');
  if (!existsSync(indexPath)) {
    throw new Error('Missing game/index.html required for SIEGEBREAK entry.');
  }
  const screenshotsDir = join(baseDir, 'screenshots');
  if (!existsSync(screenshotsDir)) {
    throw new Error('Missing screenshots directory required for SIEGEBREAK entry.');
  }
  const files = readdirSync(screenshotsDir);
  if (files.length < 3 || files.length > 4) {
    throw new Error(`Screenshots count must be between 3 and 4, found ${files.length}.`);
  }
}

/**
 * Return a one-line summary string of what was copied (counts of game files and screenshots).
 */
function describeOutput(baseDir: string): string {
  const countFiles = (dir: string): number => {
    let count = 0;
    if (!existsSync(dir)) return 0;
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name);
      if (entry.isDirectory()) {
        count += countFiles(full);
      } else {
        count++;
      }
    }
    return count;
  };
  const gameCount = countFiles(join(baseDir, 'game'));
  const screenshotCount = countFiles(join(baseDir, 'screenshots'));
  return `SIEGEBREAK packaged: ${gameCount} game files, ${screenshotCount} screenshots copied to ${out}.`;
}

verifyInputs(here);

mkdirSync(out, { recursive: true });
cpSync(join(here, 'game'), join(out, 'game'), { recursive: true });
mkdirSync(join(out, 'screenshots'), { recursive: true });
if (existsSync(join(here, 'screenshots'))) cpSync(join(here, 'screenshots'), join(out, 'screenshots'), { recursive: true });

// The scorer's own caps: only text_max_bytes shapes bytes; others refuse entries exceeding caps.
writeFileSync(
  join(out, 'dossier.json'),
  buildDossier(out, {
    text_max_bytes: 163840,
    screenshots: { max: 4, max_bytes: 262144 },
    game_max_files: 993,
    game_max_bytes: 50331648,
    game_path_max_bytes: 1000,
  }),
);

// Keep output silent apart from optional descriptor if needed, remaining strictly deterministic.
describeOutput(here);

